window.HOEREN = {"1":[{"id":"h1","type":"Erfahrungsbericht","title":"Opa Karl erzählt","title_fa":"پدربزرگ کارل تعریف می‌کند","intro_fa":"کارل، مردی بازنشسته، در یک گزارش تجربه دربارهٔ زندگی‌اش تعریف می‌کند.","s":[{"de":"Hallo, ich heiße Karl Becker und ich bin 72 Jahre alt.","fa":"سلام، اسم من کارل بکر است و ۷۲ سال دارم."},{"de":"Ich bin in einem kleinen Dorf in Bayern aufgewachsen.","fa":"من در یک روستای کوچک در بایرن بزرگ شده‌ام."},{"de":"Meine Kindheit war schön, aber wir hatten nicht viel Geld.","fa":"دوران کودکی‌ام زیبا بود، اما پول زیادی نداشتیم."},{"de":"Taschengeld habe ich nie bekommen.","fa":"من هیچ‌وقت پول توجیبی نگرفتم."},{"de":"Mit 14 Jahren musste ich schon arbeiten, denn mein Vater war plötzlich gestorben.","fa":"در ۱۴ سالگی مجبور بودم کار کنم، چون پدرم ناگهان فوت کرده بود."},{"de":"Eigentlich wollte ich Musiker werden, aber das konnte ich damals nicht.","fa":"در واقع می‌خواستم موسیقی‌دان بشوم، اما آن زمان نمی‌توانستم."},{"de":"Mit 20 bin ich nach München gezogen und habe dort als Mechaniker gearbeitet.","fa":"در ۲۰ سالگی به مونیخ رفتم و آنجا به‌عنوان مکانیک کار کردم."},{"de":"In München habe ich auch meine Frau Anna kennengelernt.","fa":"در مونیخ با همسرم آنا هم آشنا شدم."},{"de":"Ich habe mich sofort in sie verliebt.","fa":"فوراً عاشقش شدم."},{"de":"Wir haben 1976 geheiratet und zwei Kinder bekommen.","fa":"ما در سال ۱۹۷۶ ازدواج کردیم و صاحب دو فرزند شدیم."},{"de":"Heute haben wir vier Enkel, und das ist ein großes Glück für uns.","fa":"امروز چهار نوه داریم و این برای ما خوشبختی بزرگی است."},{"de":"Ich erinnere mich gern an früher, aber ich lebe auch gern heute.","fa":"با کمال میل گذشته را به یاد می‌آورم، اما از زندگی امروزم هم لذت می‌برم."},{"de":"Jetzt bin ich Rentner und habe endlich Zeit für meinen Traum: Ich lerne Gitarre!","fa":"حالا بازنشسته‌ام و بالاخره برای رؤیایم وقت دارم: دارم گیتار یاد می‌گیرم!"}],"q":[{"q":"Wo ist Karl aufgewachsen?","opts":["In München","In einem Dorf in Bayern","In Hamburg"],"a":1,"fa":"کارل می‌گوید: «در یک روستای کوچک در بایرن بزرگ شده‌ام.»"},{"q":"Warum musste Karl mit 14 Jahren arbeiten?","opts":["Sein Vater war gestorben.","Er wollte Mechaniker werden.","Er wollte viel Geld haben."],"a":0,"fa":"او می‌گوید پدرش ناگهان فوت کرده بود و برای همین مجبور بود کار کند."},{"q":"Was wollte Karl eigentlich werden?","opts":["Musiker","Mechaniker","Lehrer"],"a":0,"fa":"او می‌گوید: «می‌خواستم موسیقی‌دان بشوم.»"},{"q":"Wie viele Enkel hat Karl?","opts":["Zwei","Keine","Vier"],"a":2,"fa":"او می‌گوید: «امروز چهار نوه داریم.»"}]}],"10":[{"id":"h1","type":"Nachrichten","title":"Das Wetter am Wochenende","title_fa":"هوای آخر هفته","intro_fa":"در پایان اخبار رادیو، گوینده پیش‌بینی وضع هوای آخر هفته را می‌خواند.","s":[{"de":"Und jetzt der Wetterbericht für das Wochenende.","fa":"و حالا گزارش هواشناسی برای آخر هفته."},{"de":"Am Samstag wird es im Norden sonnig und trocken sein.","fa":"روز شنبه در شمال هوا آفتابی و خشک خواهد بود."},{"de":"Die Temperaturen werden bis auf 22 Grad steigen.","fa":"دما تا ۲۲ درجه بالا خواهد رفت."},{"de":"Das ist ein perfekter Tag für einen Ausflug an den Strand oder in den Wald.","fa":"این یک روز عالی برای گردش در ساحل یا جنگل است."},{"de":"Im Süden wird es leider bewölkt und windig sein.","fa":"در جنوب متأسفانه هوا ابری و بادی خواهد بود."},{"de":"Am Nachmittag wird es in den Bergen Gewitter geben.","fa":"بعدازظهر در کوه‌ها رعدوبرق خواهد بود."},{"de":"Wanderer sollten deshalb vorsichtig sein und früh zurückkommen.","fa":"به همین دلیل کوه‌نوردان باید مراقب باشند و زود برگردند."},{"de":"In der Nacht wird es kühl, nur etwa 8 Grad.","fa":"شب هوا خنک می‌شود، فقط حدود ۸ درجه."},{"de":"Am Sonntagmorgen wird es an vielen Flüssen neblig sein.","fa":"صبح یکشنبه کنار بسیاری از رودخانه‌ها هوا مه‌آلود خواهد بود."},{"de":"Ab Mittag wird es im ganzen Land regnen.","fa":"از ظهر در سراسر کشور باران خواهد بارید."},{"de":"Vergessen Sie also Ihren Schirm nicht!","fa":"پس چترتان را فراموش نکنید!"},{"de":"Am Montag wird die Sonne wieder scheinen.","fa":"دوشنبه دوباره خورشید خواهد تابید."},{"de":"Die Temperaturen werden dann aber nur noch bei 15 Grad liegen.","fa":"اما دما در آن روز فقط حدود ۱۵ درجه خواهد بود."}],"q":[{"q":"Wie wird das Wetter am Samstag im Norden?","opts":["Regnerisch","Neblig","Sonnig und trocken"],"a":2,"fa":"گوینده می‌گوید شنبه در شمال هوا آفتابی و خشک خواهد بود."},{"q":"Was gibt es am Samstagnachmittag in den Bergen?","opts":["Schnee","Viel Sonne","Gewitter"],"a":2,"fa":"او می‌گوید بعدازظهر در کوه‌ها رعدوبرق خواهد بود."},{"q":"Was soll man am Sonntag nicht vergessen?","opts":["Die Sonnencreme","Den Schirm","Die Sonnenbrille"],"a":1,"fa":"او می‌گوید از ظهر باران می‌بارد، پس چترتان را فراموش نکنید."},{"q":"Wie warm wird es am Montag?","opts":["15 Grad","22 Grad","8 Grad"],"a":0,"fa":"او می‌گوید دوشنبه دما فقط حدود ۱۵ درجه خواهد بود."}]}],"2":[{"id":"h1","type":"Sprachnachricht","title":"Toms neue Wohnung","title_fa":"آپارتمان جدید تام","intro_fa":"تام برای دوستش لنا یک پیام صوتی می‌فرستد و دربارهٔ آپارتمان جدیدش تعریف می‌کند.","s":[{"de":"Hallo Lena, hier ist Tom.","fa":"سلام لنا، تام هستم."},{"de":"Ich bin am Samstag in meine neue Wohnung eingezogen.","fa":"شنبه به آپارتمان جدیدم اسباب‌کشی کردم."},{"de":"Sie liegt im dritten Stock, und leider gibt es keinen Aufzug.","fa":"آپارتمان در طبقهٔ سوم است و متأسفانه آسانسور ندارد."},{"de":"Die Wohnung hat zwei Zimmer, eine kleine Küche und ein Bad.","fa":"آپارتمان دو اتاق، یک آشپزخانهٔ کوچک و یک حمام دارد."},{"de":"Die Miete ist nicht so hoch, aber die Nebenkosten sind ziemlich teuer.","fa":"اجاره خیلی بالا نیست، اما هزینه‌های جانبی نسبتاً گران است."},{"de":"Im Moment ist das Wohnzimmer noch fast leer.","fa":"فعلاً اتاق نشیمن هنوز تقریباً خالی است."},{"de":"Das Sofa steht schon an der Wand, und der Teppich liegt vor dem Sofa.","fa":"مبل حالا کنار دیوار است و فرش جلوی مبل پهن است."},{"de":"Aber das große Regal steht noch im Flur.","fa":"اما قفسهٔ بزرگ هنوز در راهرو است."},{"de":"Allein kann ich es nicht ins Wohnzimmer tragen.","fa":"تنهایی نمی‌توانم آن را به اتاق نشیمن ببرم."},{"de":"Kannst du mir am Sonntag helfen?","fa":"می‌توانی یکشنبه به من کمک کنی؟"},{"de":"Wir können das Regal zusammen neben das Fenster stellen und die Bilder an die Wand hängen.","fa":"می‌توانیم با هم قفسه را کنار پنجره بگذاریم و تابلوها را به دیوار آویزان کنیم."},{"de":"Meine Nachbarin von nebenan ist übrigens sehr nett, sie hat mir schon einen Kuchen gebracht.","fa":"راستی همسایهٔ بغلی‌ام خیلی مهربان است؛ برایم یک کیک آورده است."},{"de":"Ruf mich bitte zurück, dann lade ich dich zum Essen ein!","fa":"لطفاً به من زنگ بزن، بعد تو را به غذا دعوت می‌کنم!"}],"q":[{"q":"Wann ist Tom eingezogen?","opts":["Am Freitag","Am Sonntag","Am Samstag"],"a":2,"fa":"تام می‌گوید: «شنبه به آپارتمان جدیدم اسباب‌کشی کردم.»"},{"q":"Wo steht das große Regal jetzt?","opts":["Im Wohnzimmer","Neben dem Fenster","Im Flur"],"a":2,"fa":"او می‌گوید قفسهٔ بزرگ هنوز در راهرو است."},{"q":"Was soll Lena am Sonntag machen?","opts":["Eine Wohnung suchen","Tom helfen","Einen Kuchen backen"],"a":1,"fa":"تام از لنا می‌پرسد که آیا یکشنبه می‌تواند به او کمک کند."},{"q":"Wie ist die Nachbarin?","opts":["Unfreundlich","Laut","Nett"],"a":2,"fa":"او می‌گوید همسایهٔ بغلی‌اش خیلی مهربان است."}]}],"3":[{"id":"h1","type":"Erfahrungsbericht","title":"Mein Arbeitstag in der Bäckerei","title_fa":"روز کاری من در نانوایی","intro_fa":"سارا، کارآموز نانوایی، در یک گزارش تجربه دربارهٔ کار و روز کاری‌اش تعریف می‌کند.","s":[{"de":"Ich heiße Sara und mache eine Ausbildung als Bäckerin.","fa":"اسم من سارا است و دورهٔ آموزش حرفه‌ای نانوایی را می‌گذرانم."},{"de":"Ich bin jetzt im zweiten Jahr und arbeite in einem kleinen Betrieb in Köln.","fa":"الان در سال دوم هستم و در یک کارگاه کوچک در کلن کار می‌کنم."},{"de":"Mein Arbeitstag beginnt sehr früh, denn die Arbeit fängt um drei Uhr in der Nacht an.","fa":"روز کاری من خیلی زود شروع می‌شود، چون کار ساعت سه نیمه‌شب شروع می‌شود."},{"de":"Deshalb muss ich schon um acht Uhr abends ins Bett gehen.","fa":"به همین دلیل باید ساعت هشت شب به رختخواب بروم."},{"de":"Zuerst backen wir Brot und Brötchen, später machen wir Kuchen.","fa":"اول نان و نان‌های کوچک می‌پزیم، بعد کیک درست می‌کنیم."},{"de":"Um sechs Uhr kommen die ersten Kunden in die Bäckerei.","fa":"ساعت شش اولین مشتری‌ها به نانوایی می‌آیند."},{"de":"Ich habe diesen Beruf gewählt, weil ich gern mit den Händen arbeite.","fa":"این شغل را انتخاب کردم، چون دوست دارم با دست‌هایم کار کنم."},{"de":"Vorher habe ich ein Praktikum gemacht, und das hat mir sehr gefallen.","fa":"قبلاً یک دورهٔ کارورزی گذراندم و خیلی از آن خوشم آمد."},{"de":"Danach habe ich mich bei der Bäckerei beworben.","fa":"بعد از آن برای کار در این نانوایی درخواست دادم."},{"de":"Das Gehalt ist in der Ausbildung nicht sehr hoch.","fa":"حقوق در دورهٔ آموزش خیلی بالا نیست."},{"de":"Trotzdem bin ich zufrieden, weil mein Team sehr nett ist.","fa":"با این حال راضی هستم، چون تیمم خیلی مهربان است."},{"de":"Mein Chef sagt, dass ich gute Arbeit mache.","fa":"رئیسم می‌گوید که من خوب کار می‌کنم."},{"de":"Nach der Ausbildung möchte ich vielleicht eine eigene Bäckerei haben.","fa":"بعد از دورهٔ آموزش شاید بخواهم یک نانوایی مال خودم داشته باشم."}],"q":[{"q":"Was lernt Sara?","opts":["Bäckerin","Köchin","Friseurin"],"a":0,"fa":"سارا می‌گوید که دورهٔ آموزش نانوایی را می‌گذراند."},{"q":"Wann beginnt ihre Arbeit?","opts":["Um acht Uhr","Um drei Uhr in der Nacht","Um sechs Uhr"],"a":1,"fa":"او می‌گوید کار ساعت سه نیمه‌شب شروع می‌شود."},{"q":"Warum hat Sara diesen Beruf gewählt?","opts":["Weil das Gehalt hoch ist.","Weil sie gern mit den Händen arbeitet.","Weil ihr Vater Bäcker ist."],"a":1,"fa":"او می‌گوید: «چون دوست دارم با دست‌هایم کار کنم.»"},{"q":"Was sagt der Chef?","opts":["Dass sie früher kommen muss.","Dass sie gute Arbeit macht.","Dass sie mehr lernen muss."],"a":1,"fa":"سارا می‌گوید رئیسش معتقد است که او خوب کار می‌کند."}]}],"4":[{"id":"h1","type":"Radiobeitrag","title":"Freizeittipps für das Wochenende","title_fa":"پیشنهادهای اوقات فراغت برای آخر هفته","intro_fa":"یک گوینده در رادیوی محلی برنامه‌های تفریحی آخر هفته را معرفی می‌کند.","s":[{"de":"Willkommen bei Radio Stadtwelle mit unseren Freizeittipps für das Wochenende!","fa":"به پیشنهادهای اوقات فراغت ما برای آخر هفته در رادیو اشتات‌وله خوش آمدید!"},{"de":"Am Samstag gibt es im Stadtpark einen großen Volleyball-Wettbewerb.","fa":"شنبه در پارک شهر یک مسابقهٔ بزرگ والیبال برگزار می‌شود."},{"de":"Jeder kann mitmachen, und die beste Mannschaft gewinnt einen Preis.","fa":"همه می‌توانند شرکت کنند و بهترین تیم یک جایزه می‌برد."},{"de":"Wenn Sie lieber drinnen sind, dann besuchen Sie doch den Zirkus am Bahnhof.","fa":"اگر ترجیح می‌دهید در فضای سرپوشیده باشید، به سیرک کنار ایستگاه قطار سر بزنید."},{"de":"Der Zirkus ist dieses Jahr größer als letztes Jahr und hat mehr Tiere.","fa":"سیرک امسال بزرگ‌تر از پارسال است و حیوانات بیشتری دارد."},{"de":"Für Kinder ist das Ticket billiger als für Erwachsene, es kostet nur 8 Euro.","fa":"بلیت برای بچه‌ها ارزان‌تر از بزرگسالان است؛ فقط ۸ یورو قیمت دارد."},{"de":"Am Abend spielt die Band Nordlicht im Club Kiste.","fa":"شب گروه موسیقی نوردلیشت در کلاب کیسته اجرا دارد."},{"de":"Das Konzert beginnt um 20 Uhr, aber kommen Sie früher, denn es wird sehr voll.","fa":"کنسرت ساعت ۲۰ شروع می‌شود، اما زودتر بیایید، چون خیلی شلوغ می‌شود."},{"de":"Am Sonntag lädt das Stadtmuseum zu einem Fotokurs ein.","fa":"یکشنبه موزهٔ شهر به یک کلاس عکاسی دعوت می‌کند."},{"de":"Dort lernen Sie, wie man mit der Kamera schönere Fotos macht.","fa":"آنجا یاد می‌گیرید چطور با دوربین عکس‌های زیباتری بگیرید."},{"de":"Der Kurs ist kostenlos, aber Sie müssen sich vorher anmelden.","fa":"کلاس رایگان است، اما باید از قبل ثبت‌نام کنید."},{"de":"Und wer gern joggt, kann am Sonntagmorgen am Stadtlauf teilnehmen.","fa":"و هر کس دوست دارد بدود، می‌تواند صبح یکشنبه در مسابقهٔ دوی شهر شرکت کند."},{"de":"Das Wetter soll am Sonntag am schönsten sein, also viel Spaß draußen!","fa":"قرار است هوا یکشنبه از همه روزها بهتر باشد؛ پس در فضای باز خوش بگذرد!"}],"q":[{"q":"Was gibt es am Samstag im Stadtpark?","opts":["Ein Konzert","Einen Volleyball-Wettbewerb","Einen Fotokurs"],"a":1,"fa":"گوینده می‌گوید شنبه در پارک شهر یک مسابقهٔ بزرگ والیبال برگزار می‌شود."},{"q":"Wie viel kostet das Zirkus-Ticket für Kinder?","opts":["8 Euro","Es ist kostenlos.","18 Euro"],"a":0,"fa":"او می‌گوید بلیت سیرک برای بچه‌ها فقط ۸ یورو است."},{"q":"Warum soll man früher zum Konzert kommen?","opts":["Weil das Konzert um 18 Uhr beginnt.","Weil es sehr voll wird.","Weil die Tickets dann billiger sind."],"a":1,"fa":"او می‌گوید زودتر بیایید، چون خیلی شلوغ می‌شود."},{"q":"Was muss man für den Fotokurs machen?","opts":["Sich vorher anmelden","10 Euro bezahlen","Eine Kamera kaufen"],"a":0,"fa":"گوینده می‌گوید کلاس رایگان است، اما باید از قبل ثبت‌نام کرد."}]}],"5":[{"id":"h1","type":"Radiobeitrag","title":"Gesund durch den Winter","title_fa":"سالم در زمستان","intro_fa":"یک برنامهٔ رادیویی دربارهٔ سلامت به شنوندگان توصیه‌هایی برای پیشگیری از سرماخوردگی می‌دهد.","s":[{"de":"Im Winter erkälten sich viele Menschen.","fa":"در زمستان خیلی از مردم سرما می‌خورند."},{"de":"Man hat Husten, Schnupfen oder Halsschmerzen und fühlt sich schwach.","fa":"آدم سرفه، آبریزش بینی یا گلودرد دارد و احساس ضعف می‌کند."},{"de":"Heute sprechen wir darüber, wie Sie gesund bleiben.","fa":"امروز دربارهٔ این صحبت می‌کنیم که چطور سالم بمانید."},{"de":"Der wichtigste Tipp ist einfach: Waschen Sie sich oft die Hände, mindestens fünfmal am Tag.","fa":"مهم‌ترین توصیه ساده است: دست‌هایتان را زیاد بشویید، دست‌کم پنج بار در روز."},{"de":"Benutzen Sie dabei Seife und warmes Wasser.","fa":"برای این کار از صابون و آب گرم استفاده کنید."},{"de":"Trinken Sie außerdem viel, zum Beispiel Wasser oder Tee mit Zitrone.","fa":"علاوه بر این زیاد بنوشید، مثلاً آب یا چای با لیمو."},{"de":"Auch Bewegung ist wichtig, deshalb gehen Sie jeden Tag eine halbe Stunde spazieren.","fa":"تحرک هم مهم است، پس هر روز نیم ساعت پیاده‌روی کنید."},{"de":"Ziehen Sie sich aber warm an, denn draußen ist es kalt.","fa":"اما لباس گرم بپوشید، چون بیرون سرد است."},{"de":"Schlafen Sie genug, am besten sieben bis acht Stunden.","fa":"به اندازهٔ کافی بخوابید، بهتر است هفت تا هشت ساعت."},{"de":"Wenn Sie schon erkältet sind, bleiben Sie zu Hause und ruhen Sie sich aus.","fa":"اگر سرما خورده‌اید، در خانه بمانید و استراحت کنید."},{"de":"Bei Fieber über 39 Grad sollten Sie unbedingt zum Arzt gehen.","fa":"اگر تب بالای ۳۹ درجه دارید، حتماً باید پیش پزشک بروید."},{"de":"Der Arzt untersucht Sie und gibt Ihnen vielleicht ein Rezept für ein Mittel.","fa":"پزشک شما را معاینه می‌کند و شاید برای یک دارو به شما نسخه بدهد."},{"de":"Wir wünschen Ihnen alles Gute und viel Gesundheit!","fa":"برایتان آرزوی بهترین‌ها و سلامتی داریم!"}],"q":[{"q":"Wie oft soll man sich die Hände waschen?","opts":["Mindestens fünfmal am Tag","Nur am Abend","Einmal am Tag"],"a":0,"fa":"گوینده می‌گوید: دست‌کم پنج بار در روز دست‌هایتان را بشویید."},{"q":"Was soll man trinken?","opts":["Viel Kaffee","Wasser oder Tee mit Zitrone","Kalte Milch"],"a":1,"fa":"او می‌گوید آب یا چای با لیمو بنوشید."},{"q":"Wie lange soll man schlafen?","opts":["Fünf Stunden","Zehn Stunden","Sieben bis acht Stunden"],"a":2,"fa":"او می‌گوید بهتر است هفت تا هشت ساعت بخوابید."},{"q":"Wann soll man unbedingt zum Arzt gehen?","opts":["Bei kalten Händen","Bei Fieber über 39 Grad","Bei Husten"],"a":1,"fa":"او می‌گوید با تب بالای ۳۹ درجه حتماً پیش پزشک بروید."}]}],"6":[{"id":"h1","type":"Durchsage","title":"Weihnachtsangebote im Kaufhaus","title_fa":"پیشنهادهای کریسمس در فروشگاه بزرگ","intro_fa":"از بلندگوی یک فروشگاه بزرگ، پیشنهادهای ویژهٔ کریسمس به مشتریان اعلام می‌شود.","s":[{"de":"Liebe Kundinnen und Kunden, herzlich willkommen im Kaufhaus Sonnenberg!","fa":"مشتریان عزیز، به فروشگاه بزرگ زونن‌برگ خوش آمدید!"},{"de":"Bald ist Weihnachten, und bei uns finden Sie die schönsten Geschenke.","fa":"به‌زودی کریسمس است و نزد ما زیباترین هدیه‌ها را پیدا می‌کنید."},{"de":"Im Erdgeschoss gibt es heute frische Weihnachtsplätzchen und leckere Schokolade.","fa":"امروز در طبقهٔ همکف شیرینی‌های تازهٔ کریسمس و شکلات خوشمزه هست."},{"de":"Probieren Sie doch unsere neue Torte mit Birnen und Zimt!","fa":"کیک جدید ما را با گلابی و دارچین امتحان کنید!"},{"de":"Im zweiten Stock finden Sie elegante Ketten und silberne Ringe.","fa":"در طبقهٔ دوم گردنبندهای شیک و انگشترهای نقره‌ای پیدا می‌کنید."},{"de":"Diese Woche kostet jeder Ring nur 30 Euro.","fa":"این هفته هر انگشتر فقط ۳۰ یورو است."},{"de":"Möchten Sie Ihrer Mutter oder Ihrem Vater etwas schenken?","fa":"می‌خواهید به مادر یا پدرتان چیزی هدیه بدهید؟"},{"de":"Dann hilft Ihnen unser freundliches Team gern.","fa":"در این صورت تیم مهربان ما با کمال میل به شما کمک می‌کند."},{"de":"Wir packen Ihre Geschenke kostenlos in buntes Papier ein.","fa":"ما هدیه‌هایتان را رایگان در کاغذ رنگی بسته‌بندی می‌کنیم."},{"de":"Für die Weihnachtsfeier zu Hause haben wir rote und weiße Kerzen im Angebot.","fa":"برای جشن کریسمس در خانه، شمع‌های قرمز و سفید را با تخفیف عرضه می‌کنیم."},{"de":"Zehn Kerzen kosten nur 5 Euro.","fa":"ده شمع فقط ۵ یورو است."},{"de":"Unser Restaurant im dritten Stock bietet heute einen warmen Rinderbraten mit Bohnen an.","fa":"رستوران ما در طبقهٔ سوم امروز رست‌بیف گرم با لوبیا سرو می‌کند."},{"de":"Wir bedanken uns für Ihren Besuch und wünschen Ihnen einen schönen Einkauf!","fa":"از آمدن شما سپاسگزاریم و خرید خوبی برایتان آرزو می‌کنیم!"}],"q":[{"q":"Was gibt es im Erdgeschoss?","opts":["Rote Kerzen","Ketten und Ringe","Frische Plätzchen und Schokolade"],"a":2,"fa":"در اطلاعیه گفته می‌شود در طبقهٔ همکف شیرینی‌های تازه و شکلات خوشمزه هست."},{"q":"Wie viel kostet ein Ring diese Woche?","opts":["30 Euro","50 Euro","13 Euro"],"a":0,"fa":"گوینده می‌گوید این هفته هر انگشتر فقط ۳۰ یورو است."},{"q":"Was macht das Kaufhaus kostenlos?","opts":["Es packt die Geschenke ein.","Es gibt jedem Kunden Kuchen.","Es bringt die Geschenke nach Hause."],"a":0,"fa":"او می‌گوید هدیه‌ها را رایگان در کاغذ رنگی بسته‌بندی می‌کنند."},{"q":"Was kann man heute im Restaurant essen?","opts":["Nudeln mit Tomaten","Fisch mit Reis","Rinderbraten mit Bohnen"],"a":2,"fa":"رستوران امروز رست‌بیف گرم با لوبیا دارد."}]}],"7":[{"id":"h1","type":"Durchsage","title":"Durchsage im ICE nach Hamburg","title_fa":"اطلاعیه در قطار سریع‌السیر به هامبورگ","intro_fa":"در قطار سریع‌السیر به مقصد هامبورگ، یکی از کارکنان قطار اطلاعیه‌ای برای مسافران می‌خواند.","s":[{"de":"Meine Damen und Herren, willkommen im ICE nach Hamburg.","fa":"خانم‌ها و آقایان، به قطار ICE به مقصد هامبورگ خوش آمدید."},{"de":"Wegen einer Baustelle bei Hannover haben wir heute etwa 20 Minuten Verspätung.","fa":"امروز به دلیل یک کارگاه ساختمانی نزدیک هانوفر حدود ۲۰ دقیقه تأخیر داریم."},{"de":"Wir bitten Sie um Entschuldigung.","fa":"از شما عذرخواهی می‌کنیم."},{"de":"Unser nächster Halt ist Göttingen, ab dort fahren wir direkt bis Hamburg.","fa":"ایستگاه بعدی ما گوتینگن است؛ از آنجا مستقیم تا هامبورگ می‌رویم."},{"de":"Wir kommen voraussichtlich um 14 Uhr 35 in Hamburg an.","fa":"احتمالاً ساعت ۱۴:۳۵ به هامبورگ می‌رسیم."},{"de":"Fahrgäste nach Kiel könnten ihren Anschlusszug verpassen.","fa":"مسافران مقصد کیل ممکن است قطار بعدی‌شان را از دست بدهند."},{"de":"Bitte fragen Sie in Hamburg am Schalter nach einer neuen Verbindung.","fa":"لطفاً در هامبورگ از باجه دربارهٔ یک اتصال جدید سؤال کنید."},{"de":"Ihre Fahrkarte ist auch für einen späteren Zug gültig.","fa":"بلیت شما برای قطار بعدی هم معتبر است."},{"de":"Unser Bordrestaurant finden Sie in Wagen 5.","fa":"رستوران قطار در واگن ۵ است."},{"de":"Dort gibt es bis 13 Uhr ein warmes Frühstück.","fa":"آنجا تا ساعت ۱۳ صبحانهٔ گرم سرو می‌شود."},{"de":"Bitte lassen Sie Ihr Gepäck nicht allein auf den Plätzen liegen.","fa":"لطفاً بار و وسایلتان را تنها روی صندلی‌ها رها نکنید."},{"de":"Wenn Sie etwas verloren haben, wenden Sie sich bitte an unser Zugpersonal.","fa":"اگر چیزی گم کرده‌اید، لطفاً به کارکنان قطار مراجعه کنید."},{"de":"Wir würden uns freuen, Sie bald wieder bei uns zu begrüßen.","fa":"خوشحال می‌شویم به‌زودی دوباره از شما استقبال کنیم."},{"de":"Wir wünschen Ihnen eine angenehme Reise!","fa":"سفر خوشی برایتان آرزو می‌کنیم!"}],"q":[{"q":"Warum hat der Zug Verspätung?","opts":["Wegen einer Baustelle","Wegen einer Panne","Wegen des Wetters"],"a":0,"fa":"گوینده می‌گوید تأخیر به دلیل یک کارگاه ساختمانی نزدیک هانوفر است."},{"q":"Wann kommt der Zug in Hamburg an?","opts":["Um 13 Uhr","Um 14 Uhr 20","Um 14 Uhr 35"],"a":2,"fa":"او می‌گوید احتمالاً ساعت ۱۴:۳۵ به هامبورگ می‌رسیم."},{"q":"Was sollen die Fahrgäste nach Kiel machen?","opts":["Eine neue Fahrkarte kaufen","In Göttingen aussteigen","In Hamburg am Schalter fragen"],"a":2,"fa":"مسافران مقصد کیل باید در هامبورگ از باجه دربارهٔ اتصال جدید بپرسند."},{"q":"Wo ist das Bordrestaurant?","opts":["In Wagen 5","In Wagen 9","In Wagen 3"],"a":0,"fa":"او می‌گوید رستوران قطار در واگن ۵ است."}]}],"8":[{"id":"h1","type":"Erfahrungsbericht","title":"Wie ich Deutsch gelernt habe","title_fa":"چطور آلمانی یاد گرفتم","intro_fa":"رضا، مردی ایرانی، در یک گزارش تجربه تعریف می‌کند که چطور در آلمان زبان آلمانی یاد گرفت.","s":[{"de":"Ich heiße Reza und komme aus dem Iran.","fa":"اسم من رضا است و اهل ایران هستم."},{"de":"Als ich vor drei Jahren nach Deutschland kam, konnte ich kein Wort Deutsch.","fa":"وقتی سه سال پیش به آلمان آمدم، حتی یک کلمه آلمانی هم بلد نبودم."},{"de":"Am Anfang wusste ich oft nicht, ob die Leute mich verstehen.","fa":"اوایل اغلب نمی‌دانستم که آیا مردم حرفم را می‌فهمند یا نه."},{"de":"Deshalb habe ich einen Sprachkurs an der Volkshochschule besucht.","fa":"به همین دلیل در یک کلاس زبان در آموزشگاه عمومی بزرگسالان شرکت کردم."},{"de":"Unsere Lehrerin war streng, aber sehr gut.","fa":"معلممان سخت‌گیر بود، اما خیلی خوب."},{"de":"Jeden Tag haben wir neue Wörter gelernt und Aufgaben im Heft gemacht.","fa":"هر روز کلمه‌های جدید یاد می‌گرفتیم و تمرین‌ها را در دفتر انجام می‌دادیم."},{"de":"Wenn ich ein Wort nicht kannte, habe ich es auf eine Notiz geschrieben.","fa":"وقتی کلمه‌ای را بلد نبودم، آن را روی یک یادداشت می‌نوشتم."},{"de":"Die Notizen habe ich an meinen Kühlschrank gehängt.","fa":"یادداشت‌ها را به یخچالم می‌چسباندم."},{"de":"Außerdem bin ich oft in die Bibliothek gegangen und habe einfache Bücher gelesen.","fa":"علاوه بر این اغلب به کتابخانه می‌رفتم و کتاب‌های ساده می‌خواندم."},{"de":"Nach einem Jahr habe ich meine erste Prüfung gemacht.","fa":"بعد از یک سال اولین امتحانم را دادم."},{"de":"Der schriftliche Test war schwer, aber ich habe trotzdem bestanden.","fa":"آزمون کتبی سخت بود، اما با این حال قبول شدم."},{"de":"Ich habe 85 von 100 Punkten bekommen.","fa":"من ۸۵ امتیاز از ۱۰۰ گرفتم."},{"de":"Mein Tipp: Haben Sie keine Angst vor Fehlern und sprechen Sie viel!","fa":"توصیهٔ من: از اشتباه کردن نترسید و زیاد صحبت کنید!"}],"q":[{"q":"Wann kam Reza nach Deutschland?","opts":["Vor drei Jahren","Vor fünf Jahren","Vor einem Jahr"],"a":0,"fa":"رضا می‌گوید: «وقتی سه سال پیش به آلمان آمدم…»"},{"q":"Wie war seine Lehrerin?","opts":["Streng, aber gut","Nett, aber langweilig","Jung und lustig"],"a":0,"fa":"او می‌گوید معلمشان سخت‌گیر بود، اما خیلی خوب."},{"q":"Wohin hat Reza die Notizen gehängt?","opts":["An die Tür","An die Tafel","An den Kühlschrank"],"a":2,"fa":"او می‌گوید یادداشت‌ها را به یخچالش می‌چسباند."},{"q":"Wie viele Punkte hat Reza bekommen?","opts":["58","85","100"],"a":1,"fa":"او می‌گوید ۸۵ امتیاز از ۱۰۰ گرفته است."}]}],"9":[{"id":"h1","type":"Telefonansage","title":"Telefonansage vom Bürgeramt","title_fa":"پیام تلفنی ادارهٔ امور شهروندی","intro_fa":"کسی به ادارهٔ امور شهروندی شهر فرایبورگ زنگ می‌زند و یک پیام ضبط‌شده می‌شنود.","s":[{"de":"Guten Tag, Sie sind mit dem Bürgeramt der Stadt Freiburg verbunden.","fa":"روز بخیر، شما با ادارهٔ امور شهروندی شهر فرایبورگ تماس گرفته‌اید."},{"de":"Leider sind im Moment alle Mitarbeiter im Gespräch.","fa":"متأسفانه در حال حاضر همهٔ کارمندان مشغول صحبت هستند."},{"de":"Bitte bleiben Sie am Apparat oder rufen Sie später wieder an.","fa":"لطفاً پشت خط بمانید یا بعداً دوباره زنگ بزنید."},{"de":"Unsere Öffnungszeiten sind Montag bis Freitag von 8 bis 13 Uhr.","fa":"ساعات کاری ما دوشنبه تا جمعه از ساعت ۸ تا ۱۳ است."},{"de":"Am Donnerstag haben wir zusätzlich von 14 bis 18 Uhr offen.","fa":"پنجشنبه علاوه بر آن از ساعت ۱۴ تا ۱۸ هم باز هستیم."},{"de":"Ohne Termin ist es leider nicht möglich, einen Ausweis zu beantragen.","fa":"متأسفانه بدون وقت قبلی امکان درخواست کارت شناسایی وجود ندارد."},{"de":"Einen Termin können Sie ganz einfach im Internet vereinbaren.","fa":"وقت را می‌توانید خیلی ساده در اینترنت تعیین کنید."},{"de":"Wenn Sie einen Termin verschieben möchten, sagen Sie uns bitte mindestens einen Tag vorher Bescheid.","fa":"اگر می‌خواهید وقتتان را عقب بیندازید، لطفاً دست‌کم یک روز قبل به ما خبر بدهید."},{"de":"Bitte vergessen Sie nicht, alle Papiere mitzubringen.","fa":"لطفاً فراموش نکنید که همهٔ مدارک را همراه بیاورید."},{"de":"Dazu gehören Ihr alter Ausweis und ein aktuelles Foto.","fa":"از جملهٔ آن‌ها کارت شناسایی قدیمی و یک عکس جدید است."},{"de":"Für einen neuen Personalausweis bezahlen Sie eine Gebühr von 37 Euro.","fa":"برای کارت شناسایی جدید ۳۷ یورو هزینه می‌پردازید."},{"de":"Bürger, die nach Freiburg umgezogen sind, müssen sich innerhalb von zwei Wochen anmelden.","fa":"شهروندانی که به فرایبورگ نقل مکان کرده‌اند، باید ظرف دو هفته ثبت‌نام کنند."},{"de":"Das Formular, das Sie dafür brauchen, finden Sie auch auf unserer Webseite.","fa":"فرمی را که برای این کار لازم دارید، در وب‌سایت ما هم پیدا می‌کنید."},{"de":"Vielen Dank für Ihren Anruf.","fa":"از تماس شما سپاسگزاریم."}],"q":[{"q":"An welchem Tag hat das Bürgeramt auch am Nachmittag offen?","opts":["Am Freitag","Am Donnerstag","Am Montag"],"a":1,"fa":"در پیام گفته می‌شود پنجشنبه از ساعت ۱۴ تا ۱۸ هم باز است."},{"q":"Wie kann man einen Termin vereinbaren?","opts":["Nur am Schalter","Nur mit einem Brief","Im Internet"],"a":2,"fa":"در پیام گفته می‌شود وقت را می‌توان خیلی ساده در اینترنت تعیین کرد."},{"q":"Was kostet ein neuer Personalausweis?","opts":["18 Euro","13 Euro","37 Euro"],"a":2,"fa":"در پیام گفته می‌شود هزینهٔ کارت شناسایی جدید ۳۷ یورو است."},{"q":"Wann muss man sich nach einem Umzug anmelden?","opts":["Innerhalb von drei Tagen","Innerhalb von einem Monat","Innerhalb von zwei Wochen"],"a":2,"fa":"کسانی که به فرایبورگ نقل مکان کرده‌اند، باید ظرف دو هفته ثبت‌نام کنند."}]}]};
